# Include directories
include_directories(${CMAKE_CURRENT_SOURCE_DIR})

# Define main library target
add_library(recreemulcream SHARED native-lib.cpp)

# Link libraries for the main target
target_link_libraries(recreemulcream
 android
 log
)

# Add definitions
