#include <jni.h>
#include <string>
#include <android/native_window.h>
#include <android/native_window_jni.h>
#include <android/log.h>
#include <stdint.h>
#include <stdlib.h>
#include <fcntl.h>

// mGBA headers
#ifdef __has_include
#if __has_include("mgba/core/core.h") && !defined(ENABLE_FALLBACK_MODE)
#define HAS_MGBA_HEADERS 1
#else
#define HAS_MGBA_HEADERS 0
#endif
#else
#define HAS_MGBA_HEADERS 0
#endif

#if HAS_MGBA_HEADERS
#include <mgba/core/core.h>
#include <mgba/core/blip_buf.h>
#include <mgba/core/log.h>
#include <mgba/gba/core.h>
#include <mgba/gba/interface.h>
#include <mgba/gba/gba.h>
#include <mgba/gba/renderers/software.h>
#include <mgba-util/vfs.h>
#include <mgba-util/memory.h>
#else
// Forward declarations for stub implementation
struct mCore {
 bool (*init)(struct mCore*);
 void (*deinit)(struct mCore*);
 void (*reset)(struct mCore*);
 void (*runFrame)(struct mCore*);
 bool (*loadROM)(struct mCore*, void*);
 void (*getPixels)(struct mCore*, void*, size_t);
 void (*setKeys)(struct mCore*, uint16_t);
 bool (*saveState)(struct mCore*, void*);
 bool (*loadState)(struct mCore*, void*);

 struct mCoreConfig {
 void* dummy;
 } config;
};

struct VFile {
 void (*close)(struct VFile*);
};

// Stub functions for when the actual library is not available
static inline struct mCore* GBACoreCreate(void) { return NULL; }
static inline bool mCoreInitConfig(struct mCore* core, void* unused) { return false; }
static inline bool mCoreConfigSetIntValue(struct mCoreConfig* config, const char* key, int value) { return false; }
static inline struct VFile* VFileOpen(const char* path, int mode) { return NULL; }
static inline struct VFile* VFileMemChunk(void* unused, size_t unused2) { return NULL; }
static inline void coreDeinit(struct mCore* core) {}
#endif

// Define button codes
#define GBA_KEY_A 0
#define GBA_KEY_B 1
#define GBA_KEY_SELECT 2
#define GBA_KEY_START 3
#define GBA_KEY_RIGHT 4
#define GBA_KEY_LEFT 5
#define GBA_KEY_UP 6
#define GBA_KEY_DOWN 7
#define GBA_KEY_R 8
#define GBA_KEY_L 9

#define TAG "EmulatorMGBA"
#define LOGI(...) __android_log_print(ANDROID_LOG_INFO, TAG, __VA_ARGS__)
#define LOGE(...) __android_log_print(ANDROID_LOG_ERROR, TAG, __VA_ARGS__)

// Global state
static struct mCore* core = NULL;
static bool core_initialized = false;

// Input state
static uint16_t input_state = 0;

// Screen buffer
static uint32_t* video_buffer = NULL;
static size_t video_buffer_size = 0;

extern "C" JNIEXPORT jboolean JNICALL
Java_com_example_recreemulcream_emulation_core_EmulatorBridge_00024GbaEmulatorBridge_nativeInitialize(
 JNIEnv* env, jobject thiz, jstring rom_path) {

 // Cleanup previous core if any
 if (core) {
 #if HAS_MGBA_HEADERS
 core->deinit(core);
 coreDeinit(core);
 #endif
 core = NULL;
 core_initialized = false;
 }

 const char* path = env->GetStringUTFChars(rom_path, NULL);
 LOGI("Initializing mGBA with ROM: %s", path);

 #if HAS_MGBA_HEADERS
 // Create mCore instance
 core = GBACoreCreate();
 if (!core) {
 LOGE("Failed to create mGBA core");
 env->ReleaseStringUTFChars(rom_path, path);
 return JNI_FALSE;
 }

 // Initialize core
 core->init(core);
 mCoreInitConfig(core, NULL);

 // Set video dimensions
 mCoreConfigSetIntValue(&core->config, "width", 240);
 mCoreConfigSetIntValue(&core->config, "height", 160);

 // Open ROM
 struct VFile* rom = VFileOpen(path, O_RDONLY);
 env->ReleaseStringUTFChars(rom_path, path);

 if (!rom) {
 LOGE("Failed to open ROM file");
 core->deinit(core);
 coreDeinit(core);
 core = NULL;
 return JNI_FALSE;
 }

 if (!core->loadROM(core, rom)) {
 LOGE("Failed to load ROM");
 rom->close(rom);
 core->deinit(core);
 coreDeinit(core);
 core = NULL;
 return JNI_FALSE;
 }

 // Create video buffer
 video_buffer_size = 240 * 160 * sizeof(uint32_t);
 video_buffer = (uint32_t*)malloc(video_buffer_size);
 if (!video_buffer) {
 LOGE("Failed to allocate video buffer");
 rom->close(rom);
 core->deinit(core);
 coreDeinit(core);
 core = NULL;
 return JNI_FALSE;
 }

 // Reset core
 core->reset(core);
 core_initialized = true;

 LOGI("mGBA initialized successfully");
 return JNI_TRUE;
 #else
 LOGE("mGBA headers not found");
 return JNI_FALSE;
 #endif
}

extern "C" JNIEXPORT jint JNICALL
Java_com_example_recreemulcream_emulation_core_EmulatorBridge_00024GbaEmulatorBridge_nativeRunFrame(
 JNIEnv* env, jobject thiz, jlong surface_ptr) {

 if (!core || !core_initialized || !video_buffer) {
 LOGE("Core not initialized");
 return 0;
 }

 #if HAS_MGBA_HEADERS
 // Run one frame
 core->setKeys(core, input_state);
 core->runFrame(core);

 // Get video buffer from core
 core->getPixels(core, video_buffer, video_buffer_size);
 #endif

 // Get the ANativeWindow from the surface
 ANativeWindow* window = (ANativeWindow*)surface_ptr;
 if (!window) {
 return 16; // Skip rendering but continue emulation
 }

 // Buffer for rendering
 ANativeWindow_Buffer buffer;
 if (ANativeWindow_lock(window, &buffer, NULL) < 0) {
 return 16; // Failed to lock window
 }

 // Draw GBA screen (240x160) centered on the buffer
 int dst_width = buffer.width;
 int dst_height = buffer.height;
 int dst_stride = buffer.stride;
 uint32_t* dst_pixels = (uint32_t*)buffer.bits;

 // Calculate aspect ratio to preserve GBA's 3:2 ratio
 int max_width = dst_height * 3 / 2;
 int draw_width = (max_width < dst_width) ? max_width : dst_width;
 int draw_height = draw_width * 2 / 3;

 // Recenter if needed
 if (draw_height > dst_height) {
 draw_height = dst_height;
 draw_width = draw_height * 3 / 2;
 }

 int offset_x = (dst_width - draw_width) / 2;
 int offset_y = (dst_height - draw_height) / 2;

 // Simple nearest-neighbor scaling
 for (int y = 0; y < draw_height; y++) {
 for (int x = 0; x < draw_width; x++) {
 int src_x = x * 240 / draw_width;
 int src_y = y * 160 / draw_height;
 uint32_t pixel = video_buffer[src_y * 240 + src_x];

 // RGBA to ABGR conversion (if needed)
 int r = (pixel >> 16) & 0xFF;
 int g = (pixel >> 8) & 0xFF;
 int b = pixel & 0xFF;
 uint32_t abgr = (0xFF << 24) | (b << 16) | (g << 8) | r;

 int pos_y = offset_y + y;
 int pos_x = offset_x + x;
 if (pos_y < dst_height && pos_x < dst_width) {
 dst_pixels[pos_y * dst_stride + pos_x] = abgr;
 }
 }
 }

 // Unlock and post
 ANativeWindow_unlockAndPost(window);

 return 16; // Return frame time in ms (60 FPS = ~16ms)
}

extern "C" JNIEXPORT void JNICALL
Java_com_example_recreemulcream_emulation_core_EmulatorBridge_00024GbaEmulatorBridge_nativeUpdateInput(
 JNIEnv* env, jobject thiz, jintArray buttons) {

 if (!core_initialized) return;

 jint* buttonStates = env->GetIntArrayElements(buttons, NULL);
 jsize len = env->GetArrayLength(buttons);

 // Reset input state
 input_state = 0;

 // Map buttons to mGBA keys
 if (len >= 12) { // Make sure we have enough elements
 if (buttonStates[0]) input_state |= 1 << GBA_KEY_UP; // Up
 if (buttonStates[1]) input_state |= 1 << GBA_KEY_DOWN; // Down
 if (buttonStates[2]) input_state |= 1 << GBA_KEY_LEFT; // Left
 if (buttonStates[3]) input_state |= 1 << GBA_KEY_RIGHT; // Right
 if (buttonStates[4]) input_state |= 1 << GBA_KEY_A; // A
 if (buttonStates[5]) input_state |= 1 << GBA_KEY_B; // B
 if (buttonStates[8]) input_state |= 1 << GBA_KEY_L; // L
 if (buttonStates[9]) input_state |= 1 << GBA_KEY_R; // R
 if (buttonStates[10]) input_state |= 1 << GBA_KEY_SELECT; // Select
 if (buttonStates[11]) input_state |= 1 << GBA_KEY_START; // Start
 }

 env->ReleaseIntArrayElements(buttons, buttonStates, 0);
}

extern "C" JNIEXPORT jboolean JNICALL
Java_com_example_recreemulcream_emulation_core_EmulatorBridge_00024GbaEmulatorBridge_nativeSaveState(
 JNIEnv* env, jobject thiz) {

 if (!core_initialized) return JNI_FALSE;

 #if HAS_MGBA_HEADERS
 struct VFile* state = VFileMemChunk(NULL, 0);
 if (!state) {
 LOGE("Failed to create memory file for save state");
 return JNI_FALSE;
 }

 if (!core->saveState(core, state)) {
 LOGE("Failed to save state");
 state->close(state);
 return JNI_FALSE;
 }

 state->close(state);
 return JNI_TRUE;
 #else
 LOGE("mGBA headers not found");
 return JNI_FALSE;
 #endif
}

extern "C" JNIEXPORT jboolean JNICALL
Java_com_example_recreemulcream_emulation_core_EmulatorBridge_00024GbaEmulatorBridge_nativeLoadState(
 JNIEnv* env, jobject thiz) {

 if (!core_initialized) return JNI_FALSE;

 #if HAS_MGBA_HEADERS
 struct VFile* state = VFileMemChunk(NULL, 0);
 if (!state) {
 LOGE("Failed to create memory file for load state");
 return JNI_FALSE;
 }

 if (!core->loadState(core, state)) {
 LOGE("Failed to load state");
 state->close(state);
 return JNI_FALSE;
 }

 state->close(state);
 return JNI_TRUE;
 #else
 LOGE("mGBA headers not found");
 return JNI_FALSE;
 #endif
}

extern "C" JNIEXPORT void JNICALL
Java_com_example_recreemulcream_emulation_core_EmulatorBridge_00024GbaEmulatorBridge_nativeShutdown(
 JNIEnv* env, jobject thiz) {

 if (core_initialized && core) {
 #if HAS_MGBA_HEADERS
 core->deinit(core);
 coreDeinit(core);
 #endif
 core = NULL;
 core_initialized = false;
 }

 if (video_buffer) {
 free(video_buffer);
 video_buffer = NULL;
 }

 LOGI("mGBA emulator shut down");
}
