+import com.example.recreemulcream.emulation.input.InputHandler;
+
+import java.io.File;
+
+/**
+ * Bridge that adapts our pure Java emulator to the EmulatorBridge interface
+ * Avoids the need for native code
+ */
+public class JavaEmulatorBridge implements EmulatorBridge {
+ private static final String TAG = "JavaEmulatorBridge";
+
+ private final Context context;
+ private final JavaEmulator.EmulationType type;
+ private JavaEmulator emulator;
+ private boolean isInitialized = false;
+ private String savePath;
+
+ public JavaEmulatorBridge(Context context, JavaEmulator.EmulationType type, String savePath) {
+ this.context = context;
+ this.type = type;
+ this.emulator = new JavaEmulator(context, type);
+ this.savePath = savePath;
+ }
+
+ @Override
+ public boolean initializeEmulator(String romPath) {
+ isInitialized = emulator.loadRom(romPath);
+ if (isInitialized) {
+ emulator.start();
+ }
+ return isInitialized;
+ }
+
+ @Override
+ public int runFrame(SurfaceHolder holder) {
+ if (!isInitialized) {
+ return 0;
+ }
+
+ return emulator.runFrame(holder);
+ }
+
+ @Override
+ public void setInputHandler(InputHandler inputHandler) {
+ emulator.setInputHandler(inputHandler);
+ }
+
+ @Override
+ public boolean saveState() {
+ if (!isInitialized) {
+ return false;
+ }
+
+ return emulator.saveState();
+ }
+
+ @Override
+ public boolean loadState() {
+ if (!isInitialized) {
+ return false;
+ }
+
+ return emulator.loadState();
+ }
+
+ @Override
+ public void shutdown() {
+ if (isInitialized) {
+ emulator.stop();
+ emulator = null;
+ isInitialized = false;
+ }
+ }
+
+ /**
+ * Factory method to create the appropriate emulator bridge
+ *
+ * @param context Application context
+ * @param type Type of emulator to create
+ * @return The appropriate emulator bridge
+ */
+ public static EmulatorBridge create(Context context, String type) {
+ switch (type.toLowerCase()) {
+ case "gba":
+ String gbaPath = new File(context.getFilesDir(), "saves/gba").getAbsolutePath();
+ return new JavaEmulatorBridge(context, JavaEmulator.EmulationType.GBA, gbaPath);
+ case "snes":
+ String snesPath = new File(context.getFilesDir(), "saves/snes").getAbsolutePath();
+ return new JavaEmulatorBridge(context, JavaEmulator.EmulationType.SNES, snesPath);
+ case "ds":
+ String dsPath = new File(context.getFilesDir(), "saves/ds").getAbsolutePath();
+ return new JavaEmulatorBridge(context, JavaEmulator.EmulationType.DS, dsPath);
+ default:
+ throw new IllegalArgumentException("Unknown emulator type: " + type);
+ }
+ }
+}
