+package com.example.recreemulcream.util;

+import android.util.Log;
+
+/**
+ * Utility methods for emulator functionality
+ */
+public class EmulatorUtils {
+ private static final String TAG = "EmulatorUtils";
+
+ /**
+ * Safely tries to load a native library, falling back gracefully if it fails
+ *
+ * @param libraryName The name of the library to load
+ * @return True if library was loaded, false if using Java fallback
+ */
+ public static boolean safeLoadLibrary(String libraryName) {
+ try {
+ System.loadLibrary(libraryName);
+ Log.i(TAG, "Successfully loaded native library: " + libraryName);
+ return true;
+ } catch (UnsatisfiedLinkError e) {
+ Log.w(TAG, "Could not load native library: " + libraryName +
+ ", using Java fallback. Error: " + e.getMessage());
+ return false;
+ }
+ }
+
+ /**
+ * Check if the emulator is using native or Java implementation
+ *
+ * @return True if using native implementation, false for Java
+ */
+ public static boolean isUsingNativeImplementation() {
+ // Try loading a simple test function
+ try {
+ System.loadLibrary("recreemulcream");
+ return true;
+ } catch (UnsatisfiedLinkError e) {
+ return false;
+ }
+ }
+}
